// Host test: the core builds addresses, transactions, authorizations and event filters, and each
// result is compared byte by byte with what the official JavaScript SDK produces
// (tests/vectors/vectors.h, generated by tests/vectors/vectors.mjs).
//
// It needs no board and no network. The board provides SHA-256 and the signature; here they come
// from this file (its own SHA-256) and Monocypher (Ed25519).
//
// How to run it: see tests/host/run.sh
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "monocypher-ed25519.h"
#include "monocypher.h"
#include "stellar_mcu.h"
#include "vectors.h"

// ---------------------------------------------------------------- SHA-256 for the host
static const uint32_t K256[64] = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2};

static uint32_t rotr(uint32_t v, unsigned n) { return (v >> n) | (v << (32 - n)); }

static void sha256_block(uint32_t h[8], const uint8_t b[64]) {
  uint32_t w[64], a[8];
  for (int i = 0; i < 16; i++)
    w[i] = (uint32_t)b[4 * i] << 24 | (uint32_t)b[4 * i + 1] << 16 | (uint32_t)b[4 * i + 2] << 8 | b[4 * i + 3];
  for (int i = 16; i < 64; i++) {
    uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
    uint32_t s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
    w[i] = w[i - 16] + s0 + w[i - 7] + s1;
  }
  memcpy(a, h, sizeof a);
  for (int i = 0; i < 64; i++) {
    uint32_t s1 = rotr(a[4], 6) ^ rotr(a[4], 11) ^ rotr(a[4], 25);
    uint32_t ch = (a[4] & a[5]) ^ (~a[4] & a[6]);
    uint32_t t1 = a[7] + s1 + ch + K256[i] + w[i];
    uint32_t s0 = rotr(a[0], 2) ^ rotr(a[0], 13) ^ rotr(a[0], 22);
    uint32_t maj = (a[0] & a[1]) ^ (a[0] & a[2]) ^ (a[1] & a[2]);
    uint32_t t2 = s0 + maj;
    a[7] = a[6]; a[6] = a[5]; a[5] = a[4]; a[4] = a[3] + t1;
    a[3] = a[2]; a[2] = a[1]; a[1] = a[0]; a[0] = t1 + t2;
  }
  for (int i = 0; i < 8; i++) h[i] += a[i];
}

static void host_sha256(const uint8_t *data, size_t n, uint8_t out[32]) {
  uint32_t h[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};
  uint8_t block[64];
  size_t i = 0;
  for (; i + 64 <= n; i += 64) sha256_block(h, data + i);
  size_t rest = n - i;
  memcpy(block, data + i, rest);
  block[rest++] = 0x80;
  if (rest > 56) {
    memset(block + rest, 0, 64 - rest);
    sha256_block(h, block);
    rest = 0;
  }
  memset(block + rest, 0, 56 - rest);
  uint64_t bits = (uint64_t)n * 8;
  for (int j = 0; j < 8; j++) block[56 + j] = (uint8_t)(bits >> (56 - 8 * j));
  sha256_block(h, block);
  for (int j = 0; j < 8; j++) {
    out[4 * j] = (uint8_t)(h[j] >> 24);
    out[4 * j + 1] = (uint8_t)(h[j] >> 16);
    out[4 * j + 2] = (uint8_t)(h[j] >> 8);
    out[4 * j + 3] = (uint8_t)h[j];
  }
}

// ---------------------------------------------------------------- signature with Monocypher
static void host_sign(const uint8_t seed[32], const uint8_t public_key[32], const uint8_t *m, size_t n,
                      uint8_t signature[64]) {
  uint8_t key[64];  // Monocypher keeps the secret key as seed + public key
  memcpy(key, seed, 32);
  memcpy(key + 32, public_key, 32);
  crypto_ed25519_sign(signature, key, m, n);
  crypto_wipe(key, sizeof key);
}

static const stl_crypto CRYPTO = {host_sha256, host_sign};

// ---------------------------------------------------------------- comparison
static int g_tests = 0, g_failures = 0;
static uint8_t g_tx[1200];
static char g_b64[1700];

static void compare(const char *name, const char *got, const char *expected) {
  int ok = !strcmp(got, expected);
  g_tests++;
  if (!ok) {
    g_failures++;
    printf("  got:      %s\n  expected: %s\n", got, expected);
  }
  printf("%-30s %s\n", name, ok ? "equal" : "DIFFERENT");
}

static const char *envelope_b64(const stl_xdr *x) {
  if (x->overflow) return "(overflow)";
  stl_b64_encode(stl_tx_envelope(x), stl_tx_envelope_len(x), g_b64, sizeof g_b64);
  return g_b64;
}

static void hex(const uint8_t *d, size_t n, char *s) {
  static const char H[] = "0123456789abcdef";
  for (size_t i = 0; i < n; i++) {
    s[2 * i] = H[d[i] >> 4];
    s[2 * i + 1] = H[d[i] & 15];
  }
  s[2 * n] = 0;
}

int main(void) {
  char text[260];
  uint8_t data[32], h[32], buf[200], contract[32], soroban_data[400], public_key[32], copy[32], key[64];
  stl_xdr x;
  stl_tx base;

  // 0. The test keys: the public key is derived from the seed.
  memcpy(copy, V_SEED_A, 32);  // Monocypher wipes the seed it receives
  crypto_ed25519_key_pair(key, public_key, copy);
  if (memcmp(public_key, V_PUB_A, 32)) {
    printf("the public key derived from the seed does not match\n");
    return 1;
  }

  // 1. Addresses
  stl_addr_encode(STL_ADDR_ACCOUNT, V_PUB_A, text);
  compare("address_account", text, V_ACCOUNT_A);
  stl_addr_encode(STL_ADDR_SEED, V_SEED_A, text);
  compare("address_seed", text, V_SECRET_A);
  int round_trip = stl_addr_decode(V_ACCOUNT_B, STL_ADDR_ACCOUNT, data) && !memcmp(data, V_PUB_B, 32);
  compare("address_decode", round_trip ? "ok" : "bad", "ok");
  char tampered[57];
  strcpy(tampered, V_ACCOUNT_B);
  tampered[20] = tampered[20] == 'A' ? 'B' : 'A';
  compare("address_tampered_rejected",
          stl_addr_decode(tampered, STL_ADDR_ACCOUNT, data) ? "accepted" : "rejected", "rejected");

  // 2. Token contracts derived from the asset
  stl_asset usdc = {false, "USDC", {0}};
  stl_addr_decode(V_USDC_ISSUER, STL_ADDR_ACCOUNT, usdc.issuer);
  stl_asset xlm = {true, "", {0}};
  stl_asset_contract(&CRYPTO, V_NETWORK_ID, &xlm, contract);
  stl_addr_encode(STL_ADDR_CONTRACT, contract, text);
  compare("contract_xlm", text, V_CONTRACT_NATIVE);
  stl_asset_contract(&CRYPTO, V_NETWORK_ID, &usdc, data);
  stl_addr_encode(STL_ADDR_CONTRACT, data, text);
  compare("contract_usdc", text, V_CONTRACT_USDC);

  // 3. Classic payments
  memset(&base, 0, sizeof base);
  memcpy(base.source, V_PUB_A, 32);
  base.fee = 100;
  base.sequence = 123456789;
  base.valid_until = 1800000000;
  base.has_memo = true;
  base.memo = 4242;
  stl_tx_begin(&x, g_tx, sizeof g_tx, V_NETWORK_ID);
  stl_tx_payment(&x, &base, V_PUB_B, NULL, 12345678);
  stl_tx_sign(&x, &CRYPTO, V_SEED_A, V_PUB_A, h);
  hex(h, 32, text);
  compare("payment_xlm_hash", text, V_TX1_HASH);
  compare("payment_xlm_envelope", envelope_b64(&x), V_TX1_ENVELOPE);

  base.has_memo = false;
  stl_tx_begin(&x, g_tx, sizeof g_tx, V_NETWORK_ID);
  stl_tx_payment(&x, &base, V_PUB_B, &usdc, 25000000);
  stl_tx_sign(&x, &CRYPTO, V_SEED_A, V_PUB_A, h);
  compare("payment_usdc_envelope", envelope_b64(&x), V_TX2_ENVELOPE);

  // 4. Call to the token contract: transfer(from, to, amount). The network rejects a contract call
  //    that carries a memo, so the core leaves it out even when the transaction asks for one: with
  //    has_memo set, these envelopes still have to match the JavaScript SDK's, which carry none.
  base.has_memo = true;
  const stl_token_call transfer = {contract, "transfer", {V_PUB_A, V_PUB_B, NULL}, 2, 5000000};
  int soroban_data_len = stl_b64_decode(V_SOROBAN_DATA, strlen(V_SOROBAN_DATA), soroban_data, sizeof soroban_data);
  stl_tx_begin(&x, g_tx, sizeof g_tx, V_NETWORK_ID);
  stl_tx_token_call(&x, &base, &transfer, NULL, 0);
  stl_tx_unsigned(&x);
  compare("transfer_for_simulation", envelope_b64(&x), V_TX3_SIM);

  base.fee = V_TX3_FEE;
  stl_tx_begin(&x, g_tx, sizeof g_tx, V_NETWORK_ID);
  stl_tx_token_call(&x, &base, &transfer, soroban_data, (size_t)soroban_data_len);
  stl_tx_sign(&x, &CRYPTO, V_SEED_A, V_PUB_A, h);
  compare("transfer_envelope", envelope_b64(&x), V_TX3_ENVELOPE);

  stl_xdr_init(&x, buf, sizeof buf);
  stl_token_auth(&x, &transfer);
  stl_b64_encode(buf, x.n, g_b64, sizeof g_b64);
  compare("authorization", g_b64, V_AUTH);

  // 5. Charge with a spending allowance: transfer_from(spender, from, to, amount). The device signs
  //    and pays the fee; the operation is made on behalf of the spender account, where the
  //    device's key is a signer. This is what a card terminal sends.
  uint8_t usdc_contract[32];
  stl_asset_contract(&CRYPTO, V_NETWORK_ID, &usdc, usdc_contract);
  const stl_token_call charge = {usdc_contract, "transfer_from", {V_PUB_C, V_PUB_D, V_PUB_B}, 3, 25000000};
  stl_tx on_behalf = base;
  on_behalf.fee = 100;
  on_behalf.has_op_source = true;
  memcpy(on_behalf.op_source, V_PUB_C, 32);
  stl_tx_begin(&x, g_tx, sizeof g_tx, V_NETWORK_ID);
  stl_tx_token_call(&x, &on_behalf, &charge, NULL, 0);
  stl_tx_unsigned(&x);
  compare("transfer_from_for_simulation", envelope_b64(&x), V_TX4_SIM);

  on_behalf.fee = V_TX4_FEE;
  stl_tx_begin(&x, g_tx, sizeof g_tx, V_NETWORK_ID);
  stl_tx_token_call(&x, &on_behalf, &charge, soroban_data, (size_t)soroban_data_len);
  stl_tx_sign(&x, &CRYPTO, V_SEED_A, V_PUB_A, h);
  compare("transfer_from_envelope", envelope_b64(&x), V_TX4_ENVELOPE);

  uint8_t auth[256];  // 224 bytes with three accounts
  stl_xdr_init(&x, auth, sizeof auth);
  stl_token_auth(&x, &charge);
  stl_b64_encode(auth, x.n, g_b64, sizeof g_b64);
  compare("authorization_transfer_from", x.overflow ? "(overflow)" : g_b64, V_AUTH_CHARGE);

  // 6. Node queries and event parsing
  size_t n = stl_scval_symbol(buf, sizeof buf, "transfer");
  stl_b64_encode(buf, n, g_b64, sizeof g_b64);
  compare("topic_transfer", g_b64, V_TOPIC_TRANSFER);
  n = stl_scval_account(buf, V_PUB_B);
  stl_b64_encode(buf, n, g_b64, sizeof g_b64);
  compare("topic_account", g_b64, V_TOPIC_ACCOUNT_B);
  n = stl_account_key(buf, V_PUB_A);
  stl_b64_encode(buf, n, g_b64, sizeof g_b64);
  compare("account_key", g_b64, V_ACCOUNT_KEY_A);

  int64_t amount = 0;
  bool has_memo = false;
  uint64_t memo = 0;
  int l = stl_b64_decode(V_EVENT_INT, strlen(V_EVENT_INT), buf, sizeof buf);
  int ok = stl_event_amount(buf, (size_t)l, &amount, &has_memo, &memo) && amount == 5000000 && !has_memo;
  compare("event_int", ok ? "ok" : "bad", "ok");
  l = stl_b64_decode(V_EVENT_MAP, strlen(V_EVENT_MAP), buf, sizeof buf);
  ok = stl_event_amount(buf, (size_t)l, &amount, &has_memo, &memo) && amount == 12345678 && has_memo && memo == 4242;
  compare("event_map_with_memo", ok ? "ok" : "bad", "ok");

  // 7. Payment request (SEP-7): the plain request, and the same one saying which network it is
  // for. One check for both: if the one with the network is wrong, the comparison fails.
  size_t sep7_len = stl_sep7_pay(text, sizeof text, V_PUB_B, 25000000, &usdc, true, 4242);
  char with_network[400];
  snprintf(with_network, sizeof with_network, "%s", text);
  sep7_len = stl_sep7_network(with_network, sizeof with_network, sep7_len, "Test SDF Network ; September 2015");
  compare("sep7", sep7_len && strcmp(with_network, V_SEP7_NETWORK) == 0 ? text : with_network, V_SEP7);

  // 8. Amounts: text with 7 decimals <-> smallest units
  int64_t units = 0;
  ok = stl_amount_parse("2.5", &units) && units == 25000000;
  compare("amount_parse", ok ? "ok" : "bad", "ok");
  stl_amount_format(12345678, text, sizeof text);
  compare("amount_format", text, "1.2345678");

  printf("\n%d of %d equal\n", g_tests - g_failures, g_tests);
  return g_failures ? 1 : 0;
}
